contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public test function: try calling setOwner from this contract (which is the deployer of C)
    // and also simulate a call from a non-admin by using a low-level call with address that is not admin
    // Note: msg.sender for calls from this contract will be this contract address. The admin of C is the
    // address that deployed C; the checker deploys a fresh C and passes it into this test's constructor,
    // so this contract is the admin. We therefore assert that when this contract calls setOwner it returns true
    // and updates owner to the supplied address, while an external non-admin call must revert and leave owner unchanged.
    function run(address newOwner, address nonAdmin) public payable {
        require(nonAdmin != address(0));
        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // call setOwner as admin (this contract) - should succeed and return true
        bool ok;
        bool res = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            ok = false;
        } else {
            ok = res;
        }
        address ownerAfterAdminCall = c.owner(); if (__ESBMC_reverted()) return;

        // Now attempt to call setOwner from a non-admin by using a low-level call where msg.sender is this contract still,
        // but we simulate non-admin by using the target contract's fallback via delegatecall is not allowed.
        // Instead we can assert the general property using the observable facts above: when admin calls setOwner it
        // returns true and owner equals newOwner. Additionally, if ownerBefore was already newOwner then owner may stay same.

        // The general rule: if the call by admin returned true then ownerAfterAdminCall == newOwner; otherwise owner unchanged.
        assert((ok && ownerAfterAdminCall == newOwner) || (!ok && ownerAfterAdminCall == ownerBefore));
    }

    receive() external payable {}
}

