pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner, address nonAdmin) internal {
        vm.assume(nonAdmin != address(0));
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool ok;
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        address ownerAfterAdminCall;
        try c.owner() returns (address __r) { ownerAfterAdminCall = __r; } catch { return; }
        assertTrue((ok && ownerAfterAdminCall == newOwner) || (!ok && ownerAfterAdminCall == ownerBefore));
    }

    function testFuzz_run(address newOwner, address nonAdmin) public {
        vm.assume(newOwner.code.length == 0 && uint160(newOwner) > 0xffff && newOwner != address(this) && newOwner != address(c) && newOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && newOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(nonAdmin.code.length == 0 && uint160(nonAdmin) > 0xffff && nonAdmin != address(this) && nonAdmin != address(c) && nonAdmin != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && nonAdmin != 0x000000000000000000636F6e736F6c652e6c6f67 && nonAdmin != 0x4e59b44847b379578588920cA78FbF26c0B4956C && nonAdmin != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newOwner, nonAdmin);
    }

    receive() external payable {}
}
